mapper.select:
        select
        message.*,
        student.stu_name,
        student.stu_img,
        teachers.tea_name,
        teachers.tea_img
        from message message
        left join student student on message.send_user_id = student.id
		left join teachers teachers on message.accept_user_id = teachers.id

            and message.id = #{id}
            and message.send_user_id = #{sendUserId}
            and message.accept_user_id = #{acceptUserId}
            and message.create_time = #{createTime}
            and student.stu_name like concat('%',#{stuName},'%')
            and student.stu_img = #{stuImg}
            and teachers.tea_name like concat('%',#{teaName},'%')
            and teachers.tea_img = #{teaImg}


            limit #{current},#{pageSize}

        select count(*) from message message
        left join student student on message.send_user_id = student.id
		left join teachers teachers on message.accept_user_id = teachers.id

            and message.id = #{id}
            and message.send_user_id = #{sendUserId}
            and message.accept_user_id = #{acceptUserId}
            and message.create_time = #{createTime}
            and student.stu_name like concat('%',#{stuName},'%')
            and student.stu_img = #{stuImg}
            and teachers.tea_name like concat('%',#{teaName},'%')
            and teachers.tea_img = #{teaImg}
